DO $$ BEGIN IF EXISTS (SELECT 1 FROM issue_workflow_action_receipt WHERE lease_count <> 0 OR effect_attempt_count <> 0 OR observation_failure_count <> 0 OR effect_result <> '{}'::jsonb OR reconciliation_state <> 'none' OR last_observed_at IS NOT NULL OR bound_task_id IS NOT NULL) THEN RAISE EXCEPTION 'workflow action execution metadata contains durable records'; END IF; ALTER TABLE issue_workflow_action_receipt DROP COLUMN IF EXISTS bound_task_id, DROP COLUMN IF EXISTS last_observed_at, DROP COLUMN IF EXISTS reconciliation_state, DROP COLUMN IF EXISTS effect_result, DROP COLUMN IF EXISTS effect_key, DROP COLUMN IF EXISTS observation_failure_count, DROP COLUMN IF EXISTS effect_attempt_count, DROP COLUMN IF EXISTS lease_count; END $$;
